-- CampusMate / RTU Equipment Hub schema for Supabase (Postgres).
-- Run once in Supabase Dashboard > SQL Editor, on a fresh project.
-- Timestamps are TIMESTAMP(0) (Manila local time, no zone) so the API keeps returning "YYYY-MM-DD HH:MM:SS" as before.
-- IDs are GENERATED BY DEFAULT so backups can be restored with their original ids.

CREATE TABLE students (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  student_id VARCHAR(20) NOT NULL,
  email VARCHAR(120) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  first_name VARCHAR(50) NOT NULL,
  last_name VARCHAR(50) NOT NULL,
  course VARCHAR(80) NOT NULL,
  year_level VARCHAR(20) NOT NULL,
  status TEXT NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Suspended')),
  must_change_password BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMP(0) NOT NULL DEFAULT now()
);
-- MySQL compared text case-insensitively; keep student numbers unique that way too.
CREATE UNIQUE INDEX students_student_id_key ON students (LOWER(student_id));

CREATE TABLE admins (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username VARCHAR(40) NOT NULL,
  password VARCHAR(255) NOT NULL,
  full_name VARCHAR(100) NOT NULL,
  created_at TIMESTAMP(0) NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX admins_username_key ON admins (LOWER(username));

CREATE TABLE equipment (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  category VARCHAR(40) NOT NULL,
  total_units INT NOT NULL DEFAULT 0,
  available_units INT NOT NULL DEFAULT 0,
  description VARCHAR(500) NOT NULL DEFAULT '',
  image_url VARCHAR(500) NOT NULL DEFAULT '',
  created_at TIMESTAMP(0) NOT NULL DEFAULT now()
);

CREATE TABLE equipment_requests (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  receipt_no VARCHAR(12) NULL,
  student_id INT NOT NULL REFERENCES students(id),
  equipment_id INT NOT NULL REFERENCES equipment(id),
  purpose VARCHAR(300) NOT NULL,
  borrow_date DATE NOT NULL,
  return_date DATE NOT NULL,
  course_code VARCHAR(20) NOT NULL,
  status TEXT NOT NULL DEFAULT 'Pending Approval'
    CHECK (status IN ('Pending Approval','Approved','Rejected','Returned','Returned Damaged')),
  admin_note VARCHAR(300) NOT NULL DEFAULT '',
  waiver_signed BOOLEAN NOT NULL DEFAULT false,
  waiver_signature VARCHAR(120) NOT NULL,
  waiver_version VARCHAR(20) NOT NULL,
  waiver_signed_at TIMESTAMP(0) NOT NULL,
  processed_by INT NULL,
  processed_at TIMESTAMP(0) NULL,
  returned_at TIMESTAMP(0) NULL,
  created_at TIMESTAMP(0) NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX equipment_requests_receipt_no_key ON equipment_requests (receipt_no);
CREATE INDEX equipment_requests_status_idx ON equipment_requests (status);
CREATE INDEX equipment_requests_student_idx ON equipment_requests (student_id);

CREATE TABLE damage_reports (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  request_id INT NOT NULL REFERENCES equipment_requests(id),
  equipment_id INT NOT NULL REFERENCES equipment(id),
  student_id INT NOT NULL REFERENCES students(id),
  severity TEXT NOT NULL DEFAULT 'Minor' CHECK (severity IN ('Minor','Moderate','Severe')),
  description VARCHAR(500) NOT NULL,
  estimated_cost NUMERIC(10,2) NOT NULL DEFAULT 0,
  unusable BOOLEAN NOT NULL DEFAULT false,
  resolved BOOLEAN NOT NULL DEFAULT false,
  resolved_at TIMESTAMP(0) NULL,
  recorded_by INT NOT NULL,
  created_at TIMESTAMP(0) NOT NULL DEFAULT now()
);

CREATE TABLE notifications (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  recipient_type TEXT NOT NULL CHECK (recipient_type IN ('admin','student')),
  recipient_id INT NULL,            -- students.id for students; NULL = all PEMU admins
  kind VARCHAR(30) NOT NULL,
  message VARCHAR(600) NOT NULL,
  request_id INT NULL,
  is_read BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMP(0) NOT NULL DEFAULT now()
);
CREATE INDEX notifications_recipient_idx ON notifications (recipient_type, recipient_id, is_read);

-- Used by api/forgot_password.php and api/admin_resets.php (these were missing from the old schema).
CREATE TABLE password_resets (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  student_id INT NOT NULL REFERENCES students(id),
  status TEXT NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending','Done')),
  handled_by INT NULL,
  handled_at TIMESTAMP(0) NULL,
  created_at TIMESTAMP(0) NOT NULL DEFAULT now()
);
CREATE INDEX password_resets_status_idx ON password_resets (status);

CREATE TABLE login_attempts (
  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  identifier VARCHAR(160) NOT NULL,
  attempted_at TIMESTAMP(0) NOT NULL DEFAULT now()
);
CREATE INDEX login_attempts_idx ON login_attempts (identifier, attempted_at);

-- ---------------------------------------------------------------------------
-- SECURITY: Supabase publishes every table in "public" through a REST API that anyone with the project's
-- anon key can call. The PHP server connects as the postgres role (which bypasses RLS), so turn RLS on with
-- NO policies: the public API then sees nothing, while the PHP app keeps working.
ALTER TABLE students           ENABLE ROW LEVEL SECURITY;
ALTER TABLE admins             ENABLE ROW LEVEL SECURITY;
ALTER TABLE equipment          ENABLE ROW LEVEL SECURITY;
ALTER TABLE equipment_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE damage_reports     ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications      ENABLE ROW LEVEL SECURITY;
ALTER TABLE password_resets    ENABLE ROW LEVEL SECURITY;
ALTER TABLE login_attempts     ENABLE ROW LEVEL SECURITY;
-- Belt and braces: also remove the API roles' table privileges.
REVOKE ALL ON ALL TABLES    IN SCHEMA public FROM anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES    FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM anon, authenticated;

-- ---------------------------------------------------------------------------
-- OPTIONAL (equipment photos in Supabase Storage): a public-read bucket. Uploads and deletes only happen
-- from PHP with the service-role key, so no upload policies are needed.
INSERT INTO storage.buckets (id, name, public) VALUES ('equipment', 'equipment', true)
ON CONFLICT (id) DO NOTHING;
